    Bug 1952094 - Add AddMessageBatch() path which avoids detached nsIMsgDBHdrs. r=darktrojan


    This adds an implementation of nsIMsgLocalMailFolder.addMessageBatch() which doesn't require detached nsIMsgDBHdr objects.
    Currently only used for the MOZ_PANORAMA code, due to filtering requirements in RSS folders.

    Differential Revision: https://phabricator.services.mozilla.com/D242242

diff --git a/mailnews/base/src/nsMsgUtils.cpp b/mailnews/base/src/nsMsgUtils.cpp
index a89ee5c0a33..bb47e2f5660 100644
--- a/mailnews/base/src/nsMsgUtils.cpp
+++ b/mailnews/base/src/nsMsgUtils.cpp
@@ -1795,6 +1795,17 @@ nsresult SyncCopyStream(nsIInputStream* src, nsIOutputStream* dest,
   return NS_OK;
 }

+nsresult SyncWriteAll(nsIOutputStream* dest, const char* data, uint32_t count) {
+  while (count > 0) {
+    uint32_t n;
+    nsresult rv = dest->Write(data, count, &n);
+    NS_ENSURE_SUCCESS(rv, rv);
+    count -= n;
+    data += n;
+  }
+  return NS_OK;
+}
+
 // Used for "@mozilla.org/network/sync-stream-listener;1".
